import fs from 'node:fs';
import ts from 'typescript';
const compile = file => ts.transpileModule(fs.readFileSync(file,'utf8'), {compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText;
const url = text => 'data:text/javascript;base64,'+Buffer.from(text).toString('base64');
const effortUrl=url(compile('src/domain/memory-effort.ts'));
const {resolveMemoryEffortPolicy}=await import(effortUrl);
const {traverseMemoryEvidence}=await import(url(compile('src/domain/memory-traversal.ts').replace('"./memory-effort.js"',JSON.stringify(effortUrl))));
const {sufficientDirectFactLookup,directFactTraversalCompatible}=await import(url(compile('src/domain/memory-direct-recall.ts')));
const seed={factId:'seed',fact:'User favorite season is autumn',subject:'user',predicate:'favorite season',object:'autumn',ownerPrincipalId:'p',version:1,createdAt:1000,updatedAt:1000};
const conflict={...seed,factId:'conflict',fact:'User prefers spring',object:'spring'};
const lineage={sourceId:'s',sourceEventId:'e',sourceRevision:1,role:'user',trust:'user_assertion'};
const node=fact=>({key:'fact:'+fact.factId,item:{type:'fact',id:fact.factId,content:fact.fact,score:1,source:'facts',fact},lineage});
const discovered=[];
const result=await traverseMemoryEvidence({seeds:[node(seed)],policy:resolveMemoryEffortPolicy({effort:'fast',maxEntries:1}),now:()=>1000,expand:async(_node,cursor)=>{
 if(cursor===null)return {edges:[],cursor:'entities',work:1};
 discovered.push(conflict.factId);return {edges:[{node:node(conflict),relationship:'exact-entity'}],cursor:null,work:1};
}});
console.log(JSON.stringify({literalSufficient:sufficientDirectFactLookup('What is my favorite season?',{facts:[seed],candidateWorkBound:false},1000),discovered,selected:result.nodes.map(n=>n.item.id),trace:result.trace,actualDirectCompatibility:directFactTraversalCompatible(seed,result.nodes.map(n=>n.item.fact)),compatibilityIncludingDiscoveredFact:directFactTraversalCompatible(seed,[seed,conflict])},null,2));
